import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-table/troubleshooting.md","filePath":"dynamic-table/troubleshooting.md"}'),s={name:"dynamic-table/troubleshooting.md"};function n(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="duplicatecolumnkeyexception-duplicatefilterkeyexception" tabindex="-1"><code>DuplicateColumnKeyException</code> / <code>DuplicateFilterKeyException</code> <a class="header-anchor" href="#duplicatecolumnkeyexception-duplicatefilterkeyexception" aria-label="Permalink to &quot;`DuplicateColumnKeyException` / `DuplicateFilterKeyException`&quot;">​</a></h2><p>Two columns (or two filters) in the same table definition share a key. <code>Column::make($key)</code>/ <code>Filter::make($key)</code> keys must be unique per <code>columns()</code>/<code>filters()</code> array. Rename one.</p><h2 id="missingtablekeyexception" tabindex="-1"><code>MissingTableKeyException</code> <a class="header-anchor" href="#missingtablekeyexception" aria-label="Permalink to &quot;`MissingTableKeyException`&quot;">​</a></h2><p><code>protected string $tableKey = &#39;&#39;;</code> was never set on your <code>Table</code> subclass — it&#39;s required and checked in <code>mount()</code>. Set a stable, explicit key independent of the class name, e.g. <code>protected string $tableKey = &#39;finance.invoices&#39;;</code>.</p><h2 id="unsupportedrelationpathexception" tabindex="-1"><code>UnsupportedRelationPathException</code> <a class="header-anchor" href="#unsupportedrelationpathexception" aria-label="Permalink to &quot;`UnsupportedRelationPathException`&quot;">​</a></h2><p><code>RelationColumn::make(&#39;name&#39;)</code> (no dot) — a relation column key must be <code>{relation}.{field}</code>, e.g. <code>RelationColumn::make(&#39;country.name&#39;)</code>.</p><h2 id="invalidenumconfigurationexception" tabindex="-1"><code>InvalidEnumConfigurationException</code> <a class="header-anchor" href="#invalidenumconfigurationexception" aria-label="Permalink to &quot;`InvalidEnumConfigurationException`&quot;">​</a></h2><p><code>EnumColumn::make(&#39;status&#39;)-&gt;enum(SomeClass::class)</code> where <code>SomeClass</code> is not a backed enum (<code>enum X: string { ... }</code> / <code>enum X: int { ... }</code>). Pure (non-backed) enums aren&#39;t supported.</p><h2 id="sortablecomputedcolumnwithoutdatasourceexception-filtertargetunavailableexception" tabindex="-1"><code>SortableComputedColumnWithoutDataSourceException</code> / <code>FilterTargetUnavailableException</code> <a class="header-anchor" href="#sortablecomputedcolumnwithoutdatasourceexception-filtertargetunavailableexception" aria-label="Permalink to &quot;`SortableComputedColumnWithoutDataSourceException` / `FilterTargetUnavailableException`&quot;">​</a></h2><p>A <code>ComputedColumn</code> was marked <code>-&gt;sortable()</code> or <code>-&gt;searchable()</code> before <code>-&gt;field()</code> was called. <strong>Call order matters</strong> for this guard — put <code>-&gt;field()</code> first:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ throws</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ComputedColumn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sortable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">field</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;real_field&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ works</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ComputedColumn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">field</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;real_field&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sortable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="hasmanysortwithoutaggregateexception" tabindex="-1"><code>HasManySortWithoutAggregateException</code> <a class="header-anchor" href="#hasmanysortwithoutaggregateexception" aria-label="Permalink to &quot;`HasManySortWithoutAggregateException`&quot;">​</a></h2><p>Attempted to sort a <code>RelationColumn</code> pointing at a <code>HasMany</code>/<code>BelongsToMany</code> relation without declaring <code>-&gt;aggregate(&#39;count&#39;|&#39;sum&#39;|...)</code>. To-many relation sorting is inherently ambiguous without an aggregate — see <a href="./relationships#relation-sorting-limitations">relationships.md</a>.</p><h2 id="a-column-i-expected-to-see-isn-t-rendering" tabindex="-1">A column I expected to see isn&#39;t rendering <a class="header-anchor" href="#a-column-i-expected-to-see-isn-t-rendering" aria-label="Permalink to &quot;A column I expected to see isn&#39;t rendering&quot;">​</a></h2><p>Check in this order:</p><ol><li>Is <code>visible()</code> returning <code>false</code> (or a closure that evaluates to <code>false</code> for the current user)? An unauthorized column is completely absent — see <a href="./visibility-authorization">visibility-authorization.md</a>.</li><li>Is <code>hiddenByDefault()</code> set? The column exists but starts hidden until the user toggles it on in the column manager.</li><li>Did the user previously hide it? Check <code>user_table_preferences</code> for that user/table, or call <code>Table::resetPreferences()</code>.</li></ol><h2 id="query-count-seems-higher-than-expected" tabindex="-1">Query count seems higher than expected <a class="header-anchor" href="#query-count-seems-higher-than-expected" aria-label="Permalink to &quot;Query count seems higher than expected&quot;">​</a></h2><ul><li>Confirm the relation column you expect to be eager-loaded is actually <code>-&gt;visible()</code> (an unauthorized/hidden <code>RelationColumn</code> is never eager-loaded — see <a href="./performance">performance.md</a>).</li><li>Check for <code>RelationColumn</code>s at different first-segment relation paths — each unique first segment is one <code>with()</code> call, which is one extra query, by design (this is <em>not</em> N+1: it stays constant regardless of row count).</li><li>Verify you&#39;re not calling <code>-&gt;get()</code> somewhere outside the paginated query path.</li></ul><h2 id="stale-preferences-saved-views-after-a-table-definition-change" tabindex="-1">Stale preferences / saved views after a table definition change <a class="header-anchor" href="#stale-preferences-saved-views-after-a-table-definition-change" aria-label="Permalink to &quot;Stale preferences / saved views after a table definition change&quot;">​</a></h2><p>Both are automatically repaired on next load — <code>TablePreferences::normalize()</code> and <code>TableState::normalize()</code> (used by <code>applyView()</code>) both drop removed/renamed/unauthorized columns and filters rather than crashing. If something still looks wrong after a definition change, check whether the <em>filter key</em> or <em>column key</em> itself changed (a rename is indistinguishable from a removal+addition from the stored data&#39;s perspective — the old key is dropped, the new key starts at its definition default, nothing is &quot;migrated&quot;).</p><h2 id="pagination-lands-on-a-blank-nonexistent-page" tabindex="-1">Pagination lands on a blank/nonexistent page <a class="header-anchor" href="#pagination-lands-on-a-blank-nonexistent-page" aria-label="Permalink to &quot;Pagination lands on a blank/nonexistent page&quot;">​</a></h2><p><code>page</code> should reset to <code>1</code> automatically on search/filter/sort/per-page/saved-view changes (see <a href="./sorting-pagination#pagination-reset-behavior">sorting-pagination.md</a>). If you&#39;ve overridden <code>render()</code> or added a new mutating action, make sure it calls <code>$this-&gt;resetTablePage()</code>.</p><h2 id="livewire-cannot-set-property-or-serialization-errors" tabindex="-1">Livewire &quot;cannot set property&quot; or serialization errors <a class="header-anchor" href="#livewire-cannot-set-property-or-serialization-errors" aria-label="Permalink to &quot;Livewire &quot;cannot set property&quot; or serialization errors&quot;">​</a></h2><p>Every public property on a <code>Table</code> subclass must stay a primitive or array — never assign an Eloquent model, <code>Builder</code>, closure, or <code>Column</code>/<code>Filter</code> instance to a public property. Build those fresh inside <code>columns()</code>/<code>filters()</code>/<code>query()</code> (called every request) instead.</p><h2 id="booleanfilter-from-the-filter-panel-doesn-t-seem-to-apply" tabindex="-1"><code>BooleanFilter</code> from the filter panel doesn&#39;t seem to apply <a class="header-anchor" href="#booleanfilter-from-the-filter-panel-doesn-t-seem-to-apply" aria-label="Permalink to &quot;`BooleanFilter` from the filter panel doesn&#39;t seem to apply&quot;">​</a></h2><p>Fixed in this version: <code>TableState::normalizeBooleanFilterValue()</code> accepts both a real PHP <code>bool</code> and the string form an HTML <code>&lt;select&gt;</code> submits (<code>&#39;1&#39;</code>/<code>&#39;0&#39;</code>/<code>&#39;true&#39;</code>/<code>&#39;false&#39;</code>), while still correctly treating an empty string (the &quot;Any&quot; option) as &quot;no filter&quot; rather than <code>false</code>.</p><h2 id="a-datefilter-value-is-silently-dropped" tabindex="-1">A <code>DateFilter</code> value is silently dropped <a class="header-anchor" href="#a-datefilter-value-is-silently-dropped" aria-label="Permalink to &quot;A `DateFilter` value is silently dropped&quot;">​</a></h2><p>Check that the submitted string matches the filter&#39;s exact expected format: <code>Y-m-d</code> normally, <code>Y-m-d\\TH:i</code> if <code>-&gt;withTime()</code> is set. Strict parsing (<code>Carbon::createFromFormat()</code> plus a round-trip check) rejects anything else, including values <code>Carbon::parse()</code> would have loosely accepted — see <a href="./filters#datefilter">filters.md</a>. This is deliberate: silently mis-parsing an ambiguous date is worse than dropping the filter.</p><h2 id="a-datefilter-s-day-boundaries-look-off-by-a-few-hours" tabindex="-1">A <code>DateFilter</code>&#39;s day boundaries look off by a few hours <a class="header-anchor" href="#a-datefilter-s-day-boundaries-look-off-by-a-few-hours" aria-label="Permalink to &quot;A `DateFilter`&#39;s day boundaries look off by a few hours&quot;">​</a></h2><p>Set <code>-&gt;timezone(...)</code> explicitly if the filter&#39;s implicit default (<code>config(&#39;app.timezone&#39;)</code>) doesn&#39;t match the timezone your users actually enter dates in. &quot;Today&quot;/&quot;Between&quot;/etc. are computed relative to the filter&#39;s declared timezone, not the database&#39;s — see <a href="./filters#timezone">filters.md</a>.</p><h2 id="the-belongstofilter-picker-shows-type-to-search-and-never-returns-results" tabindex="-1">The <code>BelongsToFilter</code> picker shows &quot;Type to search…&quot; and never returns results <a class="header-anchor" href="#the-belongstofilter-picker-shows-type-to-search-and-never-returns-results" aria-label="Permalink to &quot;The `BelongsToFilter` picker shows &quot;Type to search…&quot; and never returns results&quot;">​</a></h2><p>Check the search term is at least <code>Table::BELONGS_TO_MIN_SEARCH_LENGTH</code> (2) characters, and that <code>-&gt;searchUsing([...])</code> declares real column names on the <strong>related</strong> model (not the parent table). If still empty, confirm the related model doesn&#39;t have a global scope silently excluding your test data (the picker respects the related model&#39;s own scopes by design).</p>',33)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
